// Agrega métricas de las conversaciones de las últimas 24 h
const desde = Date.now() / 1000 - 24 * 60 * 60;
const items = $input.all().map((i) => i.json);

// El campo de fecha puede llamarse fecha / fecha_ini (epoch) según la cuenta
const recientes = items.filter((c) => {
	const f = Number(c.fecha ?? c.fecha_ini ?? 0);
	return !f || f >= desde;
});

const porCanal = {};
const porUsuario = {};
for (const c of recientes) {
	const canal = String(c.id_canal ?? 'desconocido');
	porCanal[canal] = (porCanal[canal] || 0) + 1;
	const usuario = String(c.id_usuario ?? 'sin asignar');
	porUsuario[usuario] = (porUsuario[usuario] || 0) + 1;
}

const lineas = [
	`📊 Reporte diario de conversaciones`,
	`Total (últimas 24 h): ${recientes.length}`,
	'',
	'Por canal:',
	...Object.entries(porCanal).map(([k, v]) => `  • Canal ${k}: ${v}`),
	'',
	'Por agente:',
	...Object.entries(porUsuario).map(([k, v]) => `  • Usuario ${k}: ${v}`),
];

return [{ json: { resumen: lineas.join('\n'), total: recientes.length, porCanal, porUsuario } }];
